package org.sangam.core.power;

import java.util.Optional;

/**
 * Trusted, versioned case-type metadata of an operation (owner decisions 142 and 193). Whether the operation is
 * monetary, its currency and its limit-table key are declared in the deployed pack manifest (the case-type definition),
 * generated by packgen and versioned with the pack ({@link ManifestOperationMetadata}); a caller flag, request body,
 * process variable or pack input can never set or change them. An empty answer (unknown case type, version or action)
 * makes the evaluator deny.
 */
@FunctionalInterface
public interface OperationMetadata {

    /**
     * @return the classification of {@code action} on {@code caseType} version {@code caseTypeVersion} in
     *         {@code tenant}, or empty when no trusted definition says it
     */
    Optional<Classification> classify(String tenant, String caseType, int caseTypeVersion, String action);

    /**
     * @param monetary        true when the operation moves or commits money and therefore needs an amount
     * @param currency        the ISO 4217 currency the manifest declares for a monetary operation (null otherwise); a
     *                        request in another currency is denied
     * @param limitTableKey   the key of the limit table the delegated powers are read from, fixed by the manifest
     * @param metadataVersion the version of the definition the answer came from (pack id and version), recorded in the
     *                        audit
     * @param ruleCaseType    the case type the delegation table is consulted with (owner decision 222), declared in the
     *                        manifest; null when the manifest declares none. Never taken from a start variable: build
     *                        the table inputs with {@link #ruleInputs}
     */
    record Classification(boolean monetary, String currency, String limitTableKey, String metadataVersion,
                          String ruleCaseType) {

        /** The delegation table input that carries the case type. */
        public static final String CASE_TYPE_INPUT = "caseType";

        /** A classification without a declared rule case type. */
        public Classification(boolean monetary, String currency, String limitTableKey, String metadataVersion) {
            this(monetary, currency, limitTableKey, metadataVersion, null);
        }

        public Classification {
            if (ruleCaseType != null && ruleCaseType.isBlank()) {
                throw new IllegalArgumentException("a declared rule case type is not blank");
            }
            if (metadataVersion == null || metadataVersion.isBlank()) {
                throw new IllegalArgumentException("a trusted classification names its metadata version");
            }
            if (limitTableKey == null || limitTableKey.isBlank()) {
                throw new IllegalArgumentException("a trusted classification names its limit table");
            }
            if (monetary) {
                PowerDecision.requireCurrency(currency);
            } else if (currency != null) {
                throw new IllegalArgumentException("a non-monetary operation declares no currency");
            }
        }

        /**
         * The inputs of the delegation table (decision 222): {@code inputs} without any {@value #CASE_TYPE_INPUT} it
         * carried (a start variable or a process default is ignored, never consulted), with {@value #CASE_TYPE_INPUT}
         * set to the declared {@link #ruleCaseType} or left unset when the manifest declares none.
         */
        public java.util.Map<String, Object> ruleInputs(java.util.Map<String, ?> inputs) {
            java.util.Map<String, Object> out = new java.util.LinkedHashMap<>();
            if (inputs != null) {
                inputs.forEach((k, v) -> {
                    if (!CASE_TYPE_INPUT.equals(k)) {
                        out.put(k, v);
                    }
                });
            }
            if (ruleCaseType != null) {
                out.put(CASE_TYPE_INPUT, ruleCaseType);
            }
            return java.util.Collections.unmodifiableMap(out);
        }
    }
}
